"use strict";exports.id=368,exports.ids=[368],exports.modules={87368:a=>{a.exports=JSON.parse('{"site":{"attorney":"Burak Uğur \xd6zt\xfcrk, Attorney at Law","attorneyShort":"Burak Uğur \xd6zt\xfcrk","role":"Attorney at Law","monogramLabel":"Burak Uğur \xd6zt\xfcrk — home"},"nav":{"primary":"Main menu","home":"Home","practiceAreas":"Practice Areas","profile":"Profile","articles":"Articles","contact":"Contact","openMenu":"Open menu","closeMenu":"Close menu","skipToContent":"Skip to content","tools":"Tools"},"locale":{"label":"Language","change":"Change language","current":"Selected language"},"home":{"meta":{"title":"Burak Uğur \xd6zt\xfcrk, Attorney at Law","description":"An independent law practice working in corporate law, foreign direct investment, real estate acquisition, commercial contracts and arbitration."},"hero":{"label":"Law Practice","title":"Corporate law, foreign investment and dispute resolution.","registrationLabel":"Admission","languagesLabel":"Working Languages","languages":"Turkish \xb7 English \xb7 Arabic","focusLabel":"Practice Focus","focus":"Corporate law, foreign investment, dispute resolution","lead":"The practice works in company formation and restructuring, foreign direct investment, acquisition of immovable property, commercial contracts, and arbitration and dispute resolution.","contact":"Contact","appointment":"Request an appointment"},"practice":{"label":"Practice Areas","title":"Fields of work","lead":"The headings below indicate the areas in which the practice works regularly.","all":"All practice areas"},"profile":{"label":"Profile","title":"About the practice","body":"The practice is built on working directly on a limited number of matters. Each instruction begins with an examination of the applicable legislation and current judicial practice; the assessment given to the client sets out the available options and the risks attaching to each of them plainly.","link":"View profile"},"articles":{"label":"Articles","title":"Recent writing","lead":"Notes on legislation and practice, written for general information.","all":"All articles"},"contact":{"label":"Contact","title":"Requesting a meeting","body":"To request a meeting about your matter, you may use the form on the contact page or reach the office directly.","link":"Contact page"}},"practiceAreas":{"sirketler-hukuku":{"name":"Corporate Law","summary":"Incorporation and conversion, articles of association, capital increases, share transfers, shareholders\' agreements and general assembly procedure.","body":["Work in this area begins at incorporation: choice of corporate form, drafting the articles of association, structuring share capital and completing registration.","After incorporation, the practice covers capital increases and reductions, share transfers, shareholders\' agreements, general assembly and board procedures, and corporate conversions and mergers."]},"yabanci-yatirim":{"name":"Foreign Investment","summary":"Structuring foreign direct investment, establishing branches and liaison offices, sectoral permits, and work and residence permit procedures.","body":["Under the Foreign Direct Investment Law, the practice covers foreign investors setting up a company, branch or liaison office in T\xfcrkiye.","This includes identifying activities that require sectoral permits, handling work and residence permit procedures for foreign-owned companies, and post-investment regulatory compliance."]},"gayrimenkul-hukuku":{"name":"Real Estate Law","summary":"Acquisition of immovable property and land registry procedure, pre-transfer review, promise-to-sell agreements, construction servitude and condominium ownership, and leases.","body":["Before an acquisition, the practice covers reviewing the title deed record and zoning status, drafting promise-to-sell agreements, and following the transfer through the land registry.","It also covers establishing floor easement and condominium ownership, drafting lease agreements, and assessing the statutory limits that apply to real estate acquisition by foreign individuals."]},"ticari-sozlesmeler":{"name":"Commercial Contracts","summary":"Drafting and negotiating distribution, supply, services and licence agreements; governing law and jurisdiction provisions in cross-border contracts.","body":["The practice covers drafting commercial contracts — distribution, supply, service, licence and joint venture agreements in particular — and reviewing counterparty drafts.","Support is provided in determining the governing law and competent court or arbitration for cross-border contracts, and in drafting default and force majeure provisions."]},"tahkim-ve-uyusmazlik-cozumu":{"name":"Arbitration and Dispute Resolution","summary":"Drafting arbitration clauses, institutional and ad hoc arbitration proceedings, enforcement of foreign arbitral awards, mediation and litigation.","body":["The practice covers drafting arbitration clauses, determining the seat and language of arbitration, and following institutional or ad hoc arbitration proceedings.","It also covers the enforcement of foreign arbitral awards in T\xfcrkiye, mediation, and dispute resolution through litigation."]},"kisisel-verilerin-korunmasi":{"name":"Data Protection","summary":"KVKK compliance work, information notices and explicit consent texts, data inventories, transfers abroad and data breach notifications.","body":["Under Law No. 6698, the practice covers identifying data controller obligations, preparing a data inventory, and drafting privacy notices and explicit consent texts.","Support is provided in structuring cross-border data transfers in line with the legislation and in data breach notification procedures."]}},"practiceAreasPage":{"meta":{"title":"Fields of Work","description":"Work is carried out in corporate law, foreign investment, real estate law, commercial contracts, arbitration and dispute resolution, and data protection."},"label":"Fields of Work","title":"Fields of work","lead":"The headings below show the fields the practice regularly works in.","cta":"View details"},"practiceAreaDetail":{"back":"All fields of work","relatedLabel":"Related Articles","relatedEmpty":"No articles have been published in this field yet.","contactCta":"Get in touch"},"profilePage":{"meta":{"title":"Profile","description":"Burak Uğur \xd6zt\xfcrk, Attorney at Law — admitted to the Istanbul Bar Association. Working languages: Turkish, English and Arabic."},"label":"Profile","title":"Burak Uğur \xd6zt\xfcrk, Attorney at Law","intro":"Burak Uğur \xd6zt\xfcrk practises independently, admitted to the Istanbul Bar Association. The working languages are Turkish, English and Arabic, allowing direct communication with foreign investors and multinational parties.","admissionLabel":"Bar Admission","languagesLabel":"Working Languages","languages":"Turkish, English, Arabic","approachTitle":"Approach","approachBody":["Every matter begins with a review of the applicable legislation and current case law. The assessment shared with the client sets out the available options, the risks attached to each, and the likely timeframes, in plain terms.","The number of open files is kept limited so that each matter receives adequate attention. Communication with the client follows a policy of regular updates at every stage of the process."],"scopeTitle":"Fields of Work","scopeLinkText":"View fields of work","contactCta":"Get in touch"},"articlesPage":{"meta":{"title":"Articles","description":"General informational articles on corporate law, foreign investment, real estate, commercial contracts, arbitration and data protection."},"label":"Articles","title":"Latest writing","lead":"General informational articles on legislation and practice. Filter the list below by category.","filterAll":"All","filterLabel":"Category","searchLabel":"Search articles","searchPlaceholder":"Keyword","searchSubmit":"Search","empty":"No articles match this filter.","prevPage":"Previous","nextPage":"Next","pageLabel":"Page {page} of {totalPages}"},"articleDetail":{"back":"Back to all articles","tocLabel":"Contents","relatedLabel":"Related Articles"},"toolsPage":{"meta":{"title":"Calculation Tools","description":"Informational calculators for severance pay, annual leave, overtime, unemployment benefit, rent increases, alimony, sentence execution and inheritance shares under Turkish law."},"label":"Tools","title":"Legal Calculation Tools","lead":"Informational calculators based on the legislation in force. What you type stays in your browser: nothing is stored or transmitted. The results do not replace an assessment of your own circumstances.","back":"All calculation tools","otherToolsLabel":"Other Tools"},"tools":{"form":{"inputsLabel":"Details","resultLabel":"Result","submit":"Calculate","reset":"Clear","idle":"Fill in the fields and press Calculate. What you type stays in your browser.","parametersUnverified":"The statutory figures used by this tool have not yet been checked against the current period. Confirm them against the official amounts before relying on the result.","privacyNote":"What you enter is processed in your browser only; no data is stored or sent."},"parameters":{"severanceCeilingPerYear":"Severance ceiling","minimumWageGrossMonthly":"Gross minimum wage","stampDutyRate":"Stamp duty rate"},"errors":{"missingFields":"Please complete all required fields.","invalidAmount":"The amount or number entered is not valid.","endBeforeStart":"The end date must fall after the start date.","serviceTooShort":"Severance pay requires at least one full year of service.","leaveNotYetAccrued":"Annual paid leave requires at least one full year of service.","invalidContractHours":"Contractual weekly hours must be between 1 and 45.","noOvertime":"The hours entered do not exceed the contractual working week, so no overtime arises.","premiumDaysTooLow":"At least 600 premium days in the last three years are required.","invalidRatio":"The ratio must be between 0 and 100.","invalidPeriod":"The period entered is not valid.","noHeirsInOrder":"The details entered leave no heir in this order of succession.","estateEscheats":"With no heir in any order and no surviving spouse, the estate passes to the State (TCC art. 501)."},"kidem-tazminati":{"name":"Severance Pay Calculator","summary":"Calculates severance pay from the dates of employment and the all-in gross wage, applying the ceiling in force and stamp duty.","intro":"Severance pay is calculated under article 14 of Labour Act no. 1475, kept in force by provisional article 6 of Act no. 4857. Thirty days of the all-in gross wage is payable for each completed year of service, with part years apportioned. The payment is exempt from income tax; stamp duty is the only withholding. The calculation assumes the contract ended for a reason that entitles the employee to severance.","fields":{"startDate":"Start of employment","endDate":"End of employment","grossMonthlyWage":"Gross monthly wage","annualBenefits":"Total annual benefits","annualBenefitsHint":"The yearly total of regular benefits such as travel, meals, fuel and bonuses. Added to the all-in wage; leave blank if there are none."},"results":{"serviceDuration":"Length of service (full years / extra days)","dressedWage":"All-in gross monthly wage","appliedBase":"Thirty-day amount applied","gross":"Gross severance pay","stampDuty":"Stamp duty withheld","net":"Net severance pay"},"notes":{"ceilingApplied":"The all-in wage exceeds the severance ceiling in force, so the calculation has been made on the ceiling.","incomeTaxExempt":"Severance pay is exempt from income tax; amounts paid above the ceiling fall outside that exemption."}},"infaz-hesaplama":{"name":"Sentence Execution Calculator","summary":"Shows the period to conditional release, the supervised release period and the estimated time in prison, by offence date, offence type and recidivism.","intro":"The calculation follows articles 105/A and 107 of the Execution of Sentences Act no. 5275, and article 108 where the offender is a recidivist. The result is an estimate only: credit for time spent in pre-trial detention, aggregation of sentences, aggravated life and life imprisonment, the separate regimes for juvenile and ill prisoners, and offences under Act no. 3713 are not modelled here.","fields":{"sentenceYears":"Sentence — years","sentenceMonths":"Sentence — months","sentenceDays":"Sentence — days","offencePeriod":"Date of the offence","offencePeriodHint":"For offences committed before 30 March 2020 the supervised release period is three years under provisional article 6.","offenceType":"Type of offence","offenceTypeHint":"For listed offences such as intentional homicide, sexual offences and drug trafficking the conditional release ratio is two thirds.","repeatOffender":"Recidivism"},"options":{"offencePeriod_before2020":"Before 30 March 2020","offencePeriod_after2020":"On or after 30 March 2020","offenceType_general":"Offence under the general rule","offenceType_aggravated":"Listed offence (two-thirds ratio)","repeatOffender_no":"Not a recidivist","repeatOffender_yes":"Recidivist"},"results":{"totalSentence":"Total sentence (years / months / days)","appliedRatio":"Conditional release ratio","paroleDuration":"Until conditional release (years / months / days)","supervisedRelease":"Supervised release (years)","estimatedTimeServed":"Estimated time in prison (years / months / days)"},"notes":{"paroleScopeLimits":"Aggregation of sentences, aggravated life and life imprisonment, and the special regimes for juvenile, elderly and ill prisoners are not included.","paroleNoRemandCredit":"Credit for time already spent in custody is not taken into account; it shortens the actual time served.","paroleSeekCounsel":"Calculating execution requires the judgment and the offence date to be examined. This result is not an official execution calculation."}},"kira-artis-orani":{"name":"Rent Increase Calculator","summary":"Calculates the maximum lawful rent increase on renewal, based on the twelve-month average change in the consumer price index.","intro":"Under article 344 of the Code of Obligations no. 6098, an increase in rent may not exceed the change in the twelve-month averages of the consumer price index in the previous lease year. Where the contract sets a higher rate, that rate is void to the extent it exceeds the index. The 25% ceiling on residential rents was a temporary measure and expired on 1 July 2024.","fields":{"currentRent":"Current monthly rent","cpiRate":"Twelve-month average CPI change (%)","cpiRateHint":"Take the rate for the month of renewal from the official TurkStat series. It changes every month, which is why it is not built into this tool.","agreedRate":"Rate agreed in the contract (%)","agreedRateHint":"Enter the rate in your contract, if any. Below the index that rate applies; above it, the index does. Leave blank if there is none."},"results":{"currentRent":"Current rent","appliedRate":"Rate applied","increase":"Monthly increase","newRent":"New monthly rent","legalMaximum":"Maximum lawful rent","annualDifference":"Annual difference"},"notes":{"rentCapBasis":"The calculation treats the twelve-month CPI average as the ceiling under article 344. The same ceiling applies to commercial leases.","agreedRateCapped":"The rate agreed in the contract exceeds the index, so the index rate has been applied instead."}},"nafaka-artirim":{"name":"Alimony Increase Calculator","summary":"Calculates the current alimony, the monthly increase and the annual difference from the increase clause in the judgment.","intro":"Judgments commonly order alimony to rise by a set rate each year. The increase compounds: each year\'s uplift applies to the amount produced by the previous year\'s uplift. Where the judgment refers to an index rather than a rate, enter the official figure for the period. Re-setting alimony because circumstances have changed (article 176/4 of the Civil Code) is a separate action and falls outside this calculation.","fields":{"currentAlimony":"Current monthly alimony","annualRate":"Annual increase rate (%)","annualRateHint":"Enter the rate stated in the judgment. Where it refers to CPI or PPI, use the official figure for the period.","years":"Number of years to apply"},"results":{"currentAlimony":"Current alimony","appliedRate":"Annual increase rate","years":"Years","updatedAlimony":"Current monthly alimony","monthlyIncrease":"Monthly increase","annualDifference":"Annual difference"},"notes":{"alimonyCompounding":"The increase compounds: over several years the rate applies each year to the previous year\'s amount."}},"is-kazasi-tazminat":{"name":"Work Accident Damages Calculator","summary":"Calculates pecuniary loss from permanent incapacity across the known, active and passive periods, with contributory fault and the SGK deduction.","intro":"Damages for permanent incapacity are calculated by splitting the loss into the known period (from the accident to the date of calculation), the active period (to the end of working life) and the passive period (to the end of the remaining lifespan). The active period uses the progressive rent method applied by the Court of Cassation; a 10% annual increase and a 10% discount cancel out, so each active year corresponds to one year\'s earnings. The remaining lifespan comes from the TRH-2010 mortality table and is entered here by hand.","fields":{"monthlyEarning":"Net monthly earnings","monthlyEarningHint":"Net monthly earnings at the date of the accident. The known and active periods are calculated on this figure.","disabilityRatio":"Permanent incapacity ratio (%)","disabilityRatioHint":"The incapacity ratio set out in the SGK or forensic medicine report.","faultRatio":"Claimant\'s contributory fault (%)","faultRatioHint":"The share attributed to the injured party in the expert report. Damages are reduced by this proportion.","knownPeriodMonths":"Known period (months)","activePeriodYears":"Active period (years)","activePeriodYearsHint":"Years remaining from the date of calculation to the end of working life.","passivePeriodYears":"Passive period (years)","passivePeriodYearsHint":"Years from the end of working life to the end of the remaining lifespan in the TRH-2010 table.","sgkCapitalValue":"Capital value of the SGK income","sgkCapitalValueHint":"The capital value of the permanent incapacity income awarded by SGK is deducted from the damages. Leave blank if there is none."},"results":{"knownLoss":"Known period loss","activeLoss":"Active period loss","passiveLoss":"Passive period loss","grossLoss":"Total loss before fault reduction","liabilityShare":"Share of liability","afterFault":"After fault reduction","sgkDeduction":"SGK deduction","net":"Estimated pecuniary damages"},"notes":{"trh2010Source":"The remaining lifespan comes from the TRH-2010 mortality table; it varies by age and sex and is therefore not built into this tool.","progressiveRentMethod":"The active period uses the progressive rent method (10% increase, 10% discount).","expertReportRequired":"This result is not an actuarial report. In proceedings the loss is calculated by a court-appointed expert."}},"yillik-izin":{"name":"Annual Leave Calculator","summary":"Calculates annual paid leave entitlement and the accrued balance from the date employment began.","intro":"Under article 53 of Labour Act no. 4857, annual paid leave may not be less than fourteen days for service of one to five years, twenty days for more than five and less than fifteen years, and twenty-six days for fifteen years or more. For workers under eighteen or over fifty it may not fall below twenty days. Entitlement arises only after one full year of service.","fields":{"startDate":"Start of employment","referenceDate":"Calculation date","usedDays":"Leave days taken","ageGroup":"Worker\'s category","ageGroupHint":"For workers under eighteen or over fifty, annual leave may not fall below twenty days."},"options":{"ageGroup_standard":"Aged between 18 and 50","ageGroup_protected":"Under 18 or over 50"},"results":{"completedYears":"Completed years of service","currentEntitlement":"Entitlement for this year (days)","accrued":"Total accrued leave (days)","used":"Leave taken (days)","balance":"Leave balance (days)"},"notes":{"leaveIsMinimum":"The statutory periods are minimums and may be increased by the employment or collective agreement.","usedExceedsAccrued":"The leave taken appears to exceed the leave accrued. Please check the values entered."}},"fazla-mesai":{"name":"Overtime Pay Calculator","summary":"Calculates gross pay for hours beyond forty-five a week at 150%, and hours beyond a shorter contractual week at 125%.","intro":"Under article 41 of Labour Act no. 4857, work beyond forty-five hours a week is overtime and is paid at 150% of the hourly rate. Where the contract sets a working week shorter than forty-five hours, work between that figure and forty-five is \\"extra time\\" and is paid at 125%. Overtime may not exceed 270 hours a year. The hourly rate is the gross monthly wage divided by 225.","fields":{"grossMonthlyWage":"Gross monthly wage","contractWeeklyHours":"Contractual weekly hours","contractWeeklyHoursHint":"Enter a figure only if the contract sets fewer than forty-five hours. Otherwise leave it at 45.","actualWeeklyHours":"Hours actually worked per week","weeks":"Number of weeks"},"results":{"hourlyRate":"Gross hourly rate","overtimeHours":"Overtime (hours)","overtimePay":"Overtime pay (150%)","extraTimeHours":"Extra time (hours)","extraTimePay":"Extra time pay (125%)","total":"Total gross entitlement"},"notes":{"grossFigures":"The figures are gross; tax and social security deductions have not been applied.","overtimeCapExceeded":"The overtime calculated exceeds the annual cap of 270 hours. Exceeding the cap does not extinguish the right to payment."}},"issizlik-maasi":{"name":"Unemployment Benefit Calculator","summary":"Calculates the monthly unemployment benefit from earnings over the last four months and premium days, with the ceiling and the payment period.","intro":"Under article 50 of Unemployment Insurance Act no. 4447, the daily benefit is 40% of the average daily gross earnings subject to premium over the last four months. It may not exceed 80% of the gross minimum wage. The payment period is 180, 240 or 300 days according to premium days in the last three years. Stamp duty is the only deduction from the benefit.","fields":{"averageGrossMonthly":"Average monthly gross earnings, last four months","averageGrossMonthlyHint":"The monthly average of gross earnings subject to premium over the last four months.","premiumDays":"Premium days in the last three years","premiumDaysHint":"Entitlement requires at least 600 premium days in the last three years and 120 days of continuous service."},"results":{"grossMonthly":"Gross monthly benefit","stampDuty":"Stamp duty withheld","netMonthly":"Net monthly benefit","benefitDays":"Payment period (days)","benefitMonths":"Payment period (months)","totalBenefit":"Total net benefit"},"notes":{"benefitConditions":"Entitlement depends on the contract having ended for one of the reasons listed in the Act and on applying within the time limit.","benefitCeilingApplied":"The calculated benefit exceeds 80% of the gross minimum wage, so the ceiling has been applied."}},"miras-payi":{"name":"Inheritance Share Calculator","summary":"Calculates the statutory shares and reserved portions of the surviving spouse, descendants, parents and siblings under the parentela system.","intro":"Under articles 495 to 501 of the Turkish Civil Code the estate is divided by orders of succession. The first order is the descendants, the second the parents and their descendants, the third the grandparents. An heir in a nearer order excludes every more remote order. The surviving spouse inherits alongside whichever order is called, at a fraction that rises with its remoteness. Reserved portions are set out in article 506; the reserved portion of siblings was abolished in 2007.","fields":{"estateValue":"Net value of the estate","estateValueHint":"The net estate after the matrimonial property regime has been settled and debts deducted.","spouse":"Surviving spouse","childCount":"Number of children (descendants)","parentsAlive":"Number of surviving parents","parentsAliveHint":"Relevant only where there are no descendants. A predeceased parent\'s share passes to that parent\'s own descendants, that is, to the siblings.","siblingCount":"Number of siblings"},"options":{"spouse_yes":"Yes","spouse_no":"No","parentsAlive_0":"Neither surviving","parentsAlive_1":"One surviving","parentsAlive_2":"Both surviving"},"results":{"spouseShare":"Surviving spouse\'s share","perChildShare":"Share per child","childrenTotal":"Children\'s total share","perParentShare":"Share per parent","parentsTotal":"Parents\' total share","perSiblingShare":"Share per sibling","siblingsTotal":"Siblings\' total share","reservedTotal":"Total reserved portion","disposable":"Disposable portion"},"notes":{"inheritanceMaritalRegime":"The calculation runs on the net estate after the matrimonial property regime is settled. The surviving spouse\'s participation claim is separated before the estate is divided and is often larger than the inheritance share.","inheritanceScopeLimits":"Disinheritance, disclaimer, adoption, gifts subject to abatement and representation through a sibling\'s descendants are not included.","inheritanceSiblingsNoReserve":"The reserved portion of siblings was abolished by Act no. 5650 in 2007.","inheritanceSpouseAloneAssumption":"With no descendants, parents or siblings, no heir in the third order has been assumed either, so the whole estate passes to the surviving spouse."}}},"contactPage":{"meta":{"title":"Contact","description":"Contact details and a form for requesting a consultation are set out below."},"label":"Contact","title":"Request a Consultation","formLabel":"Request Form","requiredNote":"Fields marked with an asterisk are required.","lead":"You may use the form below to request a consultation about your matter, or contact the office directly. Information submitted through the form is used solely to assess your request.","directLabel":"Direct Contact","officeLabel":"Office Address","form":{"name":"Full name","email":"Email","phone":"Phone (optional)","subject":"Subject","message":"Your message","consent":"I have read the <link>KVKK Information Notice</link> and consent to the processing of my personal data on that basis.","submit":"Send","submitting":"Sending…","success":"Your message has been received. You will be contacted as soon as possible.","errorGeneric":"Your message could not be sent. Please try again later.","errorValidation":"Please complete the form fully and correctly.","errorRateLimit":"Too many attempts in a short time. Please try again later.","errorConsent":"You must accept the KVKK Information Notice to continue."}},"legalPages":{"kvkk":{"nav":"KVKK Information Notice"},"gizlilik":{"nav":"Privacy Policy"}},"article":{"readingTime":"{minutes} min read","publishedOn":"Published {date}","categoryLabel":"Category"},"footer":{"navTitle":"Site","officeTitle":"Office","contactTitle":"Contact","legalTitle":"Legal Notice","barRegistration":"{bar} — Registry no: {registryNo}","kvkk":"KVKK Information Notice","privacy":"Privacy Policy","rights":"\xa9 {year} Burak Uğur \xd6zt\xfcrk. All rights reserved.","phone":"Telephone","email":"E-mail","whatsapp":"WhatsApp"},"disclaimer":{"title":"Legal Notice","body":"The content on this site is provided for general information. It does not constitute legal advice and does not create an attorney–client relationship. Before deciding on any particular dispute or transaction, legal advice on your own circumstances should be obtained. Legislation and judicial practice change, and the content is not guaranteed to be current."},"notFound":{"label":"Error 404","title":"The page you were looking for was not found","body":"The link may have been moved or removed. You can continue from the home page.","home":"Return to the home page"},"error":{"label":"Error","title":"An unexpected error occurred","body":"The request could not be completed. You may wish to reload the page.","retry":"Try again"},"admin":{"login":{"meta":{"title":"Admin Sign In"},"eyebrow":"Admin Panel","title":"Sign In","email":"Email","password":"Password","submit":"Sign In","submitting":"Signing in…","errorValidation":"Please enter your email and password.","errorRateLimit":"Too many attempts. Please try again later.","errorInvalid":"Incorrect email or password."},"nav":{"dashboard":"Overview","messages":"Messages","articles":"Articles","password":"Change Password","logout":"Sign Out","viewSite":"View site"},"dashboard":{"title":"Overview","welcome":"Welcome, {name}.","messagesStat":"Unread messages","articlesStat":"Published articles","translationTitle":"Translation Status","translationLead":"Shows which languages each article group has been published in.","statusPublished":"Published","statusDraft":"Draft","statusMissing":"Missing","articlesComingSoon":"Article editing will be available from this panel soon."},"messages":{"title":"Messages","empty":"No messages yet.","statusNew":"New","statusRead":"Read","statusArchived":"Archived","markRead":"Mark as read","archive":"Archive","delete":"Delete","back":"All messages","from":"From","subject":"Subject","receivedOn":"Received","consentGiven":"KVKK consent given: {date}","deleteConfirm":"This message will be permanently deleted."},"password":{"title":"Change Password","current":"Current Password","new":"New Password","confirm":"New Password (again)","submit":"Update Password","submitting":"Updating…","success":"Your password has been updated.","errorValidation":"The new password must be at least 12 characters and match the confirmation.","errorCurrent":"The current password is incorrect.","errorGeneric":"The password could not be updated."}}}')}};